A streaming platform wants to display different messages and buttons based on a user's subscription status. How does the following component achieve this behavior?

```jsx
import { useState } from "react";

const SubscriptionStatus = () => {
  const [isSubscribed, setIsSubscribed] = useState(false);
  const toggleSubscription = () => {
    setIsSubscribed((prevState) => !prevState);
  };

  return (
    <div>
      <h1>
        {isSubscribed
          ? "You are a Premium Member!"
          : "Subscribe to Unlock Premium Features"}
      </h1>

      <button onClick={toggleSubscription}>
        {isSubscribed ? "Cancel Subscription" : "Subscribe Now"}
      </button>
    </div>
  );
};

export default SubscriptionStatus;
```

