Considering given code snippet, what happens when a user clicks the `Post Comment` button?

```jsx
import React, { useState } from 'react';

const CommentForm = () => {
  const [comments, setComments] = useState([]);
  const [name, setName] = useState("");
  const [commentText, setCommentText] = useState("");

  const onAddComment = (event) => {
    event.preventDefault();
    const newComment = { id: comments.length + 1, name, commentText };
    setComments([...comments, newComment]);
    setName("");
    setCommentText("");
  };

  return (
    <form onSubmit={onAddComment}>
      <input 
        value={name} 
        onChange={(e) => setName(e.target.value)} 
        placeholder="Your Name"
      />

      <input 
        value={commentText} 
        onChange={(e) => setCommentText(e.target.value)} 
        placeholder="Your Comment"
      />

      <button type="submit">Post Comment</button>
    </form>
  );
};

export default CommentForm;
```

What will be the className of the `Popular` button in the rendered output of this component when selectedCategory is `POPULAR`?

```jsx
import React, { useState } from "react";
import "./CategoryFilter.css";

const CategoryFilter = () => {
  const [selectedCategory, setSelectedCategory] = useState("ALL");

  const categories = [
    { id: "ALL", displayText: "All" },
    { id: "POPULAR", displayText: "Popular" },
    { id: "NEW", displayText: "New" },
    { id: "TRENDING", displayText: "Trending" },
  ];

  const onCategoryChange = (categoryId) => {
    setSelectedCategory(categoryId);
  };

  return (
    <div className="categories-container">
      <h2>Shop by Category</h2>
      <ul className="category-list">
        {categories.map((category) => {
          const isActive = selectedCategory === category.id;
          const activeClassName = isActive ? "active-category" : "";

          return (
            <li key={category.id} className="category-item">
              <button
                type="button"
                className={`category-button ${activeClassName}`}
                onClick={() => onCategoryChange(category.id)}
              >
                {category.displayText}
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
};
```

