The following code attempts to toggle a task's `completed` status when clicked, but it's not working correctly. Identify the fix that correctly follows React state update principles.

```jsx
import React, { useState } from "react";
import { v4 as uuidv4 } from "uuid";

const TodoApp = () => {
  const [tasks, setTasks] = useState([
    { id: uuidv4(), text: "Learn React", completed: false },
    { id: uuidv4(), text: "Build a project", completed: false },
  ]);

  const toggleTaskCompletion = (id) => {
    setTasks((prevTasks) => {
      return prevTasks.map((task) => {
        if (task.id === id) {
          task.completed = !task.completed;
          return task;
        }
        return task;
      });
    });
  };

  return (
    <div>
      <h1>Todo List</h1>
      <ul>
        {tasks.map((task) => (
          <li
            key={task.id}
            onClick={() => toggleTaskCompletion(task.id)}
            style={{ textDecoration: task.completed ? "line-through" : "none" }}
          >
            {task.text}
          </li>
        ))}
      </ul>
    </div>
  );
};
```

