```jsx
const toggleTaskCompletion = (id) => {
  const updatedTasks = [...tasks];
  const taskIndex = updatedTasks.findIndex((task) => task.id === id);
  updatedTasks[taskIndex].completed = !updatedTasks[taskIndex].completed;
